import json
G=[[1]*23 for _ in range(29)]
for c in list(range(10,19))+[20,21]: G[13][c]=3
for r in range(14,23): G[r][10]=3; G[r][21]=3
for r in [14,16,17]: G[r][13]=3
for c in range(10,22): G[23][c]=3
# Connect every pair of existing 3s along each row or column, marking intervening background cells 2.
for r in range(29):
    cols=[c for c,x in enumerate(G[r]) if x==3]
    for a,b in zip(cols,cols[1:]):
        for c in range(a+1,b):
            if G[r][c]==1: G[r][c]=2
for c in range(23):
    rows=[r for r in range(29) if G[r][c]==3]
    for a,b in zip(rows,rows[1:]):
        for r in range(a+1,b):
            if G[r][c]==1: G[r][c]=2
assert len(G)==29 and all(len(row)==23 for row in G)
print(json.dumps(G,separators=(',',':')))
